def build_alternating_list(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)

    # Step 1: locate cell with value 1
    x, y = -1, -1
    for i in range(n(n):
        for j in range(n):
            if grid[i][j] == 1:
                x, y = i, j
                break
        if x != -1:
            break

    # Step 2: collect valid orthogonal neighbors
    neighbors = []
    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nx, ny = x + dx, y + dy
        if 0 <= nx < n and 0 <= ny < n:
            neighbors.append(grid[nx][ny])

    # Step 3: smallest value among valid neighbors
    mn = min(neighbors) if neighbors else 0

    # Step 4: build and return alternating list
    res = []
    for i in range(k):
        if i % 2 == 0:
            res.append(1)
        else:
            res.append(mn)
    return res
