def largest_prime_factor(n: int) -> int:
    """
    Returns the largest prime factor of a positive integer n.
    Uses trial division optimized by checking only up to sqrt(n).
    """
    if n < 2:
        raise ValueError("n must be greater than 1")

    # Remove factors of 2
    if n % 2 == 0:
        while n % 2 == 0:
            n //= 2
        if n == 1:
            return 2

    # Check odd factors up to sqrt(n)
    factor = 3
    while factor * factor <= n:
        if n % factor == 0:
            while n % factor == 0:
                n //= factor
        factor += 2

    # If n is still greater than 1, it's a prime factor
    return n if n > 1 else factor - 2

